check("classic: pitch %.1f Hz is %.1f Hz" % (frequency, expected), abs(frequency - expected) < expected * 0.01)
check("classic: looped for %.2f s" % length, length > 1.0)
clean, classic = image_energy(clean_samples), image_energy(classic_samples)
check("classic adds images above the file's bandwidth (%.5f vs %.5f)" % (classic, clean), classic > clean * 10)

# Doppler: a sound that comes from an entity is shifted in pitch when the entity or the listener moves. Both are moved a unit
# every 50 ms (about 20 meters per second), toward or away from each other along Z.
def play_moving(listener_step, source_step, scale=1.0, distance=1.0, name="tone.wav", extra=""):
	body = (
		's = Load3DSound("%s")\nLoopSound s\nlistener = CreatePivot()\nsource = CreatePivot()\nPositionEntity source, 0, 0, 100\n'
		"CreateListener listener, 0, %f, %f\nc = EmitSound(s, source)\n%s\n"
		"For i = 1 To 30\n\tMoveEntity listener, 0, 0, %f\n\tMoveEntity source, 0, 0, %f\n\tDelay 50\nNext\n"
		'DebugLog "playing " + ChannelPlaying(c)\n'
	) % (name, scale, distance, extra, listener_step, source_step)
	with open("play.bb", "w") as source:
		source.write(body)
	if procutil.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZLLVM_HEADLESS", None)
	procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	return samples_after(list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2]), 0.9, 0.4)


def crossings_frequency(segment):
	crossings = [i for i in range(1, len(segment)) if segment[i - 1] < 0 <= segment[i]]
	return OUTPUT_RATE * (len(crossings) - 1) / (crossings[-1] - crossings[0]) if len(crossings) > 2 else 0.0


def samples_after(samples, start, length):
	"""The pitch of a stretch of the sound, from `start` seconds after it got loud, so that the shift has settled."""
	loud = [i for i, v in enumerate(samples) if abs(v) > 300]
	first = loud[0] + int(start * OUTPUT_RATE)
	return crossings_frequency(samples[first : first + int(length * OUTPUT_RATE)])


expected = tone("tone.wav", 22050, 1, 16)
for what, listener_step, source_step, scale, distance, low, high in (
	("standing still", 0, 0, 1.0, 1.0, 0.99, 1.01),
	("source moving away", 0, 1, 1.0, 1.0, 0.90, 0.97),
	("source moving toward the listener", 0, -1, 1.0, 1.0, 1.03, 1.12),
	("listener moving toward the source", 1, 0, 1.0, 1.0, 1.03, 1.12),
	("listener moving away from the source", -1, 0, 1.0, 1.0, 0.90, 0.97),
	("both moving the same way", 1, 1, 1.0, 1.0, 0.99, 1.01),
	("doppler scale 0", 0, 1, 0.0, 1.0, 0.99, 1.01),
	("doppler scale 2 shifts twice as far", 0, 1, 2.0, 1.0, 0.80, 0.94),
	("distance scale 0.5 halves the speeds", 0, 1, 1.0, 0.5, 0.95, 0.99),
):
	frequency = play_moving(listener_step, source_step, scale, distance)
	check("doppler, %s: %.1f Hz is %.2f to %.2f of %.1f Hz" % (what, frequency, low, high, expected), expected * low < frequency < expected * high)

# The listener settings of BlitzLLVM change the same shift after CreateListener. A radius divides the direction by more than the distance,
# so a source 100 to 130 units away with radii of 300 in all moves away at about 40% of its speed as far as the shift is concerned.
for what, extra, low, high in (
	("ListenerDoppler 2 shifts twice as far", "ListenerDoppler 2", 0.80, 0.94),
	("ListenerDistance 0.5 halves the speeds", "ListenerDistance 0.5", 0.95, 0.99),
	("SpeedOfSound 680 halves the shift", "SpeedOfSound 680", 0.95, 0.99),
	("ChannelDoppler 0", "ChannelDoppler c, 0", 0.99, 1.01),
	("a radius weakens the shift close by", "ListenerRadius 200\nChannelRadius c, 100", 0.965, 0.995),
):
	frequency = play_moving(0, 1, extra=extra)
	check("doppler, %s: %.1f Hz is %.2f to %.2f of %.1f Hz" % (what, frequency, low, high, expected), expected * low < frequency < expected * high)

# The shift is quick but not a jump: a source that stands still and then drives off is heard shifting within a few frames.
def play_start_stop():
	body = (
		's = Load3DSound("tone.wav")\nLoopSound s\nlistener = CreatePivot()\nsource = CreatePivot()\nPositionEntity source, 0, 0, 100\n'
		"CreateListener listener, 0, 1, 1\nc = EmitSound(s, source)\n"
		"For i = 1 To 10\n\tDelay 50\nNext\n"
		"For i = 1 To 40\n\tMoveEntity source, 0, 0, 3\n\tDelay 50\nNext\n"
	)
	with open("play.bb", "w") as source:
		source.write(body)
	if procutil.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZLLVM_HEADLESS", None)
	procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	return list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])


samples = play_start_stop()
loud = [i for i, v in enumerate(samples) if abs(v) > 300][0]
window = int(0.02 * OUTPUT_RATE)
pitches = [crossings_frequency(samples[loud + i * window : loud + (i + 1) * window]) for i in range(1, 90)]
pitches = [p for p in pitches if p > 0]
settled = min(pitches)
# The speed changes at once (the source stands still and then moves 3 units in a step), and the pitch follows within a few tens of
# milliseconds: no half second of gliding, but no overshoot or wobble on the way either.
start = next(i for i, p in enumerate(pitches) if p < expected * 0.98)
done = next(i for i, p in enumerate(pitches) if p < expected - 0.9 * (expected - settled))
wobble = max(max(0.0, pitches[i + 1] - pitches[i]) for i in range(start, len(pitches) - 1)) / expected
check(
	"doppler follows a change of speed quickly: the pitch goes from %.1f to %.1f Hz, 90%% of it within %d ms, wobble %.1f%%" % (pitches[0], settled, (done - start + 1) * 20, wobble * 100),
	pitches[0] > expected * 0.98 and settled < expected * 0.93 and (done - start) * 20 <= 60 and wobble < 0.05,
)

# Volume falloff: the peak of a sound that is `units` away from the listener, relative to the same sound next to it. The runtime's own
# curve ("new") is 1 / (1 + rolloff * meters * 0.05); BLITZLLVM_VOLUME_FALLOFF=soloud gives 1 / (1 + rolloff * (meters - 1)) as SoLoud does and
# =legacy the one of the original (FMOD 3), meters ^ -rolloff, both from a meter on.
def play_distance(units, rolloff, distance, model):
	body = (
		's = Load3DSound("tone.wav")\nLoopSound s\nlistener = CreatePivot()\nsource = CreatePivot()\nPositionEntity source, 0, 0, %f\n'
		"CreateListener listener, %f, 1, %f\nc = EmitSound(s, source)\nFor i = 1 To 20\n\tDelay 50\nNext\n"
	) % (units, rolloff, distance)
	with open("play.bb", "w") as source:
		source.write(body)
	if procutil.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	env.pop("BLITZLLVM_VOLUME_FALLOFF", None)
	if model != "new":
		env["BLITZLLVM_VOLUME_FALLOFF"] = model
	procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	samples = list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])
	return max(abs(v) for v in samples[OUTPUT_RATE // 2 :])


for model in ("new", "soloud", "legacy"):
	reference = play_distance(0, 1.0, 1.0, model)
	for units, rolloff, distance in ((10, 1.0, 1.0), (100, 1.0, 1.0), (10, 2.0, 1.0), (100, 0.0, 1.0), (50, 1.0, 0.5), (0.5, 1.0, 1.0)):
		meters = units * distance
		if model == "new":
			wanted = 1.0 / (1.0 + rolloff * meters * 0.05)
		elif meters <= 1.0:
			wanted = 1.0
		elif model == "soloud":
			wanted = 1.0 / (1.0 + rolloff * (meters - 1.0))
		else:
			wanted = meters**-rolloff
		gain = play_distance(units, rolloff, distance, model) / reference
		check("%s falloff at %g units, rolloff %g, distance scale %g: gain %.3f is %.3f" % (model, units, rolloff, distance, gain, wanted), abs(gain - wanted) < 0.03)

# The volume is right from the first sample and without Delay, RenderWorld or Flip ever being called (a program that only waits in a loop), and
# also without a listener: it is then at the origin with the options that FMOD starts with (rolloff 1, doppler 1, distance 1), like the original.
def play_emitted(body):
	with open("play.bb", "w") as source:
		source.write(body)
	if procutil.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZLLVM_HEADLESS", None)
	env.pop("BLITZLLVM_VOLUME_FALLOFF", None)
	procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	samples = list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])
	start = [i for i, v in enumerate(samples) if abs(v) > 300][0]
	return max(abs(v) for v in samples[start : start + OUTPUT_RATE // 10])  # The first 100 ms.


EMIT = 'Local s = Load3DSound("tone.wav")\nLocal source = CreatePivot()\nPositionEntity source, 0, 0, %d\n%sLocal c = EmitSound(s, source)\n%s'
WAIT = "Local t = MilliSecs()\nWhile MilliSecs() - t < 500\nWend\n"
reference = play_emitted(EMIT % (0, "CreateListener CreatePivot(), 1, 1, 1\n", "Delay 500\n"))
for what, listener, after in (
	("waiting in a loop", "CreateListener CreatePivot(), 1, 1, 1\n", WAIT),
	("no listener", "", "Delay 500\n"),
	("no listener, waiting in a loop", "", WAIT),
	("an emitter that is freed at once", "CreateListener CreatePivot(), 1, 1, 1\n", "FreeEntity source\nDelay 500\n"),
	("a freed listener", "Local l = CreateListener(CreatePivot(), 1, 1, 1)\nFreeEntity l\n", "Delay 500\n"),
):
	gain = play_emitted(EMIT % (100, listener, after)) / reference
	wanted = 1.0 / (1.0 + 100 * 0.05)
	check("falloff from the first sample, %s: gain %.3f is %.3f" % (what, gain, wanted), abs(gain - wanted) < 0.03)

# Programs that draw every frame never call Delay, so the position of what they emit from has to be followed while they render and
# flip, and a program that sets ChannelVolume every frame (as the original allows) must not undo it for the time that the frame takes. A sound to the right of the listener comes out of the right speaker, and the pitch still follows the movement. Skipped (77)
# without a window.
def play_rendering(source_x, listener_step=0, source_step=0, seconds=1.5):
	body = (
		'Graphics3D 160, 120, 0, 2\ncam = CreateCamera()\ns = Load3DSound("tone.wav")\nLoopSound s\nlistener = CreatePivot()\nsource = CreatePivot()\n'
		"PositionEntity source, %f, 0, 100\nCreateListener listener, 0, 1, 1\nc = EmitSound(s, source)\nstart = MilliSecs()\ntick = start\n"
		"While MilliSecs() - start < %d\n\tIf MilliSecs() - tick >= 50\n\t\ttick = tick + 50\n\t\tMoveEntity listener, 0, 0, %f\n\t\tMoveEntity source, 0, 0, %f\n\tEndIf\n"
		"\tChannelVolume c, 1.0\n\tbusy = MilliSecs()\n\twhile MilliSecs() - busy < 20\n\twend\n\tUpdateWorld\n\tRenderWorld\n\tFlip\nWend\n"
	) % (source_x, int(seconds * 1000), listener_step, source_step)
	with open("play.bb", "w") as source:
		source.write(body)
	if procutil.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZLLVM_HEADLESS", None)
	procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	if not os.path.exists("sdlaudio.raw"):
		print("no disk audio driver or window")
		raise SystemExit(77)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	both = struct.unpack("<%dh" % (count * 2), data[: count * 4])
	return list(both[0::2]), list(both[1::2])  # The first half second is left out, the sound is only placed from the first frame on.


tone("tone.wav", 22050, 1, 16)
for what, x, side in (("right of the listener", 500, "right"), ("left of the listener", -500, "left"), ("in front of the listener", 0, "both")):
	left, right = (channel[OUTPUT_RATE // 2 :] for channel in play_rendering(x))
	peak_left, peak_right = max(abs(v) for v in left), max(abs(v) for v in right)
	if side == "right":
		ok = peak_right > 1000 and peak_left < peak_right * 0.5
	elif side == "left":
		ok = peak_left > 1000 and peak_right < peak_left * 0.5
	else:
		ok = peak_left > 1000 and 0.8 < peak_right / peak_left < 1.25
	check("3D sound %s while rendering: peaks %d left, %d right" % (what, peak_left, peak_right), ok)
frequency = samples_after(play_rendering(0, 0, 1)[0], 0.9, 0.4)
check("doppler while rendering, source moving away: %.1f Hz is below %.1f Hz" % (frequency, expected), expected * 0.90 < frequency < expected * 0.97)

# The sound of movies (OpenMovie), which plays on a stream of its own: a tone of 440 Hz for 3 seconds in a movie of every format. The movies
# are the ones of tests/suite/movies, whose picture is not looked at here.
movies = os.path.join(os.path.dirname(fixtures), "suite", "movies")
for movie in ("colors.mpg", "colors.avi", "colors.mp4", "colors.webm"):
	shutil.copyfile(os.path.join(movies, movie), movie)
	with open("play.bb", "w") as source:
		source.write('m = OpenMovie("%s")\nDebugLog "opened " + m\nWhile MoviePlaying(m)\n\tDelay 20\nWend\n' % movie)
	if procutil.run([blitzcc] + OPTIONS + ["play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZLLVM_HEADLESS", None)
	run = procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read() if os.path.exists("sdlaudio.raw") else b""
	count = len(data) // 4
	samples = list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])
	frequency, smoothness, length = analyze(samples)
	check("movie %s: pitch %.1f Hz is 440 Hz" % (movie, frequency), abs(frequency - 440.0) < 440.0 * 0.01)
	check("movie %s: sound lasts %.2f s of a 3 s movie" % (movie, length), 2.4 < length < 3.6)

# MovieVolume scales the sound of a movie, from silence to the full sound.
peaks = {}
for volume in ("1.0", "0.5", "0.0"):
	with open("play.bb", "w") as source:
		source.write('m = OpenMovie("colors.mp4")\nMovieVolume m, %s\nWhile MoviePlaying(m)\n\tDelay 20\nWend\n' % volume)
	if procutil.run([blitzcc, "play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZLLVM_HEADLESS", None)
	procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read() if os.path.exists("sdlaudio.raw") else b""
	count = len(data) // 4
	peaks[volume] = max([abs(v) for v in struct.unpack("<%dh" % (count * 2), data[: count * 4])] + [0])
check("MovieVolume: the peak is %d at 1, %d at 0.5 and %d at 0" % (peaks["1.0"], peaks["0.5"], peaks["0.0"]), peaks["1.0"] > 1000 and 0.45 < peaks["0.5"] / peaks["1.0"] < 0.55 and peaks["0.0"] < 10)

# The sound of a movie plays on a channel of the mixer: MovieChannel gives it, MovieBus picks its bus, and EmitMovie makes it come from an
# entity, with the distance volume of 3D sounds (0.167 at 100 units with the default curve) and no doppler shift on a moving entity.
def movie_peak(setup):
	with open("play.bb", "w") as source:
		source.write('m = OpenMovie("colors.mp4")\n%s\nWhile MoviePlaying(m)\n\tDelay 20\nWend\n' % setup)
	if procutil.run([blitzcc, "play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZLLVM_HEADLESS", None)
	run = procutil.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read() if os.path.exists("sdlaudio.raw") else b""
	count = len(data) // 4
	samples = list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])
	return max([abs(v) for v in samples] + [0]), samples, run.stderr.decode(errors="replace")


full = peaks["1.0"]
for what, setup, ratio in (
	("ChannelVolume on MovieChannel", "ChannelVolume MovieChannel(m), 0.5", 0.5),
	("MovieBus", "b = CreateAudioBus()\nAudioBusVolume b, 0.5\nMovieBus b\nm2 = OpenMovie(\"colors.mp4\")\nCloseMovie m\nm = m2", 0.5),
	("ChannelBus on MovieChannel", "b = CreateAudioBus()\nAudioBusVolume b, 0.5\nChannelBus MovieChannel(m), b", 0.5),
	("EmitMovie 100 units away", "CreateListener CreatePivot()\np = CreatePivot()\nPositionEntity p, 0, 0, 100\nEmitMovie m, p", 0.167),
	("EmitMovie and back to the speakers", "CreateListener CreatePivot()\np = CreatePivot()\nPositionEntity p, 0, 0, 100\nEmitMovie m, p\nEmitMovie m, 0", 1.0),
):
	peak, samples, log = movie_peak(setup)
	check("movie, %s: peak %d is %.3f of %d" % (what, peak, ratio, full), abs(peak - full * ratio) <= full * 0.04 + 2)
peak, samples, log = movie_peak("CreateListener CreatePivot()\np = CreatePivot()\nPositionEntity p, 0, 0, 10\nEmitMovie m, p\nWhile MoviePlaying(m)\n\tMoveEntity p, 0, 0, 1\n\tDelay 20\nWend")
frequency, smoothness, length = analyze(samples)
check("movie, EmitMovie from a moving entity has no doppler shift: %.1f Hz is 440 Hz" % frequency, abs(frequency - 440.0) < 440.0 * 0.01)

# Opus decodes at 48 kHz whatever the file was recorded at, so it has to be resampled to play at the right pitch. The fixtures are a
# 960 Hz tone (50 samples per cycle at 48 kHz) of half a second, as .opus (Ogg Opus) and as Opus packets in an .ogg file.
for fixture in ("tone.opus", "tone_in_ogg.ogg"):
	shutil.copyfile(os.path.join(fixtures, fixture), fixture)
	samples, log = play(fixture)
	frequency, smoothness, length = analyze(samples)
	check("%s: pitch %.1f Hz is 960 Hz" % (fixture, frequency), abs(frequency - 960.0) < 960.0 * 0.01)
	check("%s: looped for %.2f s of a 0.5 s file" % (fixture, length), length > 1.0 and "playing 1" in log)
	samples, log = play(fixture, loop=False)
	frequency, smoothness, length = analyze(samples)
	check("%s: one shot of %.2f s lasts as long as the 0.5 s file" % (fixture, length), 0.4 < length < 0.65 and "playing 0" in log)

sys.exit(1 if failures else 0)
